/**
 * ModeSwitch's states fixture in element form, with the React fixture's entry
 * names, so a contract's `when <state>` names the same entry in every shell. Each
 * entry is the markup a page writes, and what its script sets once the elements
 * are defined.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/mode-switch.ts`. Never edit it by hand.
 */
import { holding, listen, type ComponentStates } from '@polymorph/elements'

import './ModeSwitch'

export const states: ComponentStates = {
  component: 'ModeSwitch',
  entries: [
    {
      name: 'uncontrolled — the document’s preference',
      html: `<poly-mode-switch label="Appearance"></poly-mode-switch>`,
      subject: 'poly-mode-switch',
      expect: { role: 'radiogroup', 'data-size': 'md' },
    },
    {
      name: 'controlled — the application holds the choice',
      html: `<poly-mode-switch label="Appearance"></poly-mode-switch>`,
      subject: 'poly-mode-switch',
      setup: (find) => {
        const held = holding({ value: 'light' as 'light' | 'dark' | 'system' })
        const e0 = find('poly-mode-switch', 0)
        held.bind('value', e0, 'value')
        listen(e0, 'poly-change', (value) => held.set('value', value))
      },
      expect: { role: 'radiogroup' },
    },
    {
      name: 'sm',
      html: `<poly-mode-switch label="Appearance" value="dark" size="sm"></poly-mode-switch>`,
      subject: 'poly-mode-switch',
      expect: { 'data-size': 'sm' },
    },
    {
      name: 'disabled — while the application saves the last choice',
      html: `<poly-mode-switch label="Appearance" value="system" disabled></poly-mode-switch>`,
      subject: 'poly-mode-switch',
      expect: { 'data-disabled': '' },
    },
    {
      name: 'localized',
      html: `<poly-mode-switch label="Apparence" value="light" messages='{"light":"Clair","dark":"Sombre","system":"Système"}'></poly-mode-switch>`,
      subject: 'poly-mode-switch',
    },
  ],
}
